if(!exists('build_transaction_features'))library(creditratingsystem)
local({
 date<-'2024-01-03';coverage<-function(status='COMPLETE')list(status=status,known_at=date,observed_from='2024-01-01',complete_through=date);tx<-function(id,amount,code,d='2024-01-02',account='a',transfer=NULL,counterparty=NULL)list(transaction_id=id,release_seq=1,account_id=account,posted_at=d,value_at=d,known_at=d,amount=amount,currency='EUR',kind='ORIGINAL',category_code=code,transfer_id=transfer,counterparty_own_account_id=counterparty);balance<-function(id,account,date,amount)list(balance_id=id,release_seq=1,account_id=account,observed_at=date,known_at=date,closing_balance=amount,currency='EUR');mapping<-list(mapping_id='local',version='1',known_at='2024-01-01',categories=list(wage='SALARY',food='CONSUMPTION',loan='BORROWING',refund='REFUND',transfer='OWN_TRANSFER',business='BUSINESS_REVENUE',draw='OWNER_DRAW'));calculate<-function(rows,balances=list(),status='COMPLETE')build_transaction_features(rows,balances,mapping,coverage(status),'c',list('a','b'),date,date,2,'EUR')
