 reverse$amount<-21;stopifnot(inherits(tryCatch(calculate(list(original,reverse)),error=function(e)e),'error'));stopifnot(inherits(tryCatch(calculate(list(tx('out',-60,'transfer',transfer='p',counterparty='b'),tx('in',59,'transfer',account='b',transfer='p',counterparty='a'))),error=function(e)e),'error'))
})
